"""Synthetic AVC resolution changes with two B frames; no service media."""
from pathlib import Path
import re
import shutil
import subprocess

lines = ['// Generated by generate-transition.py; synthetic red AVC with B frames.',
         '#pragma once', '#include <array>', '#include <span>', '#include <cstdint>',
         'namespace EsvmNalTransition {']
for name, size in [('Old', '64x48'), ('New', '96x64')]:
    data = subprocess.check_output([shutil.which('ffmpeg'), '-hide_banner', '-loglevel', 'error',
        '-f', 'lavfi', '-i', f'color=c=red:s={size}:r=25', '-frames:v', '6', '-pix_fmt', 'yuv420p',
        '-c:v', 'libx264', '-preset', 'medium', '-threads', '1',
        '-vf', 'scale=in_color_matrix=bt601:out_color_matrix=bt709',
        '-x264-params', 'bframes=2:b-adapt=0:keyint=30:scenecut=0:aud=1:colorprim=bt709:transfer=bt709:colormatrix=bt709',
        '-f', 'h264', 'pipe:1'])
    packets, packet = [], bytearray()
    def emit(label, value):
        lines.append(f'inline constexpr std::array<uint8_t, {len(value)}> {name}{label} {{')
        for i in range(0, len(value), 16):
            lines.append('    ' + ', '.join(f'0x{x:02x}' for x in value[i:i+16]) + ',')
        lines.append('};')
    for nal in filter(None, re.split(b'\x00\x00(?:\x00)?\x01', data)):
        kind = nal[0] & 31
        if kind in (7, 8):
            emit('Sps' if kind == 7 else 'Pps', nal)
        elif kind == 9:
            if packet:
                packets.append(packet)
                packet = bytearray()
        elif kind in (1, 5):
            packet += b'\x00\x00\x00\x01' + nal
    if packet:
        packets.append(packet)
    assert len(packets) == 6
    for i, packet in enumerate(packets):
        emit(f'Au{i}', packet)
    lines.append(f'inline const std::array<std::span<const uint8_t>, 6> {name}Packets {{' +
                 ', '.join(f'{name}Au{i}' for i in range(6)) + '};')
lines += ['// Fixed x264 b-adapt=0 decode order for six frames.',
          'inline constexpr std::array<int, 6> PresentationOrder {0, 3, 1, 2, 5, 4};', '}', '']
Path(__file__).with_name('transition.h').write_text('\n'.join(lines), encoding='utf-8')
